        self.priorities = {}
        self._state = {}
        # Fingerprint captured alongside every snapshot: the ordered
        # (name, sorted dependencies, priority) triples of the run's
        # closure and the closure's exact member set. resume=True
        # compares a fresh fingerprint to this one before reusing
