def _fingerprint(self, run_order):
    # Structural identity of one run's scope, in priority
    # topological order: each entry records the task name, its
    # direct dependencies (order-normalized) and the priority that
    # helped determine the sequence. Two identical fingerprints mean
    # names, dependencies and priorities are unchanged for the
    # closure; identical member sets mean the scope is unchanged.
    return tuple(
        (name, tuple(sorted(self.deps[name])), self.priorities[name])
        for name in run_order
    )

def _prepare_resume(self, run_order):
    # Verify resume=True against the most recent snapshot without
    # calling any task or replacing the snapshot. Returns the set of
    # nodes whose completed result may be reused.
    if not self._state or self._state_fingerprint is None:
        raise TaskResumeError("no_previous_run")
    if self._fingerprint(run_order) != self._state_fingerprint:
        # The ordered triples already encode names, dependencies and
        # priorities; a scope (closure member set) difference that
        # happens to share the same triples is reported separately
        # below.
        raise TaskResumeError("graph_changed")
    if set(run_order) != set(self._state):
        raise TaskResumeError("scope_changed")
    return {
        name
        for name in run_order
        if self._state[name]["status"] == "completed"
    }

